const e = $input.first().json || {};
const ex = e.execution || {};
const wf = e.workflow || {};
const msg = String((ex.error && ex.error.message) || 'unknown error').slice(0, 300);
const link = ex.url || (ex.id && wf.id ? `http://localhost:5679/workflow/${wf.id}/executions/${ex.id}` : '(no execution id)');
const name = wf.name || wf.id || 'unknown workflow';
return [{ json: { text: `[grocery-n8n] ${name} failed at ${ex.lastNodeExecuted || '?'}: ${msg} — ${link}` } }];
